const categoryByClass = Object.freeze({
  cpu_saturation: 'infra',
  memory_leak: 'infra',
  db_lock_contention: 'database',
  replication_lag: 'database',
  error_rate_spike: 'application',
  normal: null
});
const severityMap = Object.freeze({ 5: 'P1', 4: 'P2', 3: 'P3', 2: 'P4', 1: 'P4' });
const steps = Array.isArray($json.intermediateSteps) ? $json.intermediateSteps : [];
const predictorStep = steps.find(step => String(step.action?.tool || '').replace(/[^a-z0-9]/gi, '').toLowerCase() === 'predictortool');
let predictor = predictorStep?.observation ?? {};
if (typeof predictor === 'string') {
  try { predictor = JSON.parse(predictor); } catch (_) { predictor = {}; }
}
if (Array.isArray(predictor) && predictor.length === 1) predictor = predictor[0];
const incidentClass = predictor?.incident_class;
const rawSeverity = predictor?.severity;
const severity = rawSeverity;
const confidence = predictor?.confidence;
const ewmaSeverity = predictor?.scores?.ewma?.severity;
const knownClass = Object.prototype.hasOwnProperty.call(categoryByClass, incidentClass);
const validSeverity = typeof rawSeverity === 'number' && Number.isInteger(rawSeverity) && Object.prototype.hasOwnProperty.call(severityMap, rawSeverity);
const validConfidence = typeof confidence === 'number' && Number.isFinite(confidence) && confidence >= 0 && confidence <= 1;
const validMethod = predictor?.method === 'ewma-floor';
const validScores = predictor?.scores !== null && typeof predictor?.scores === 'object' && !Array.isArray(predictor?.scores) && Object.prototype.hasOwnProperty.call(predictor.scores, 'ewma') && Object.prototype.hasOwnProperty.call(predictor.scores, 'classifier');
const validEwmaSeverity = typeof ewmaSeverity === 'number' && Number.isInteger(ewmaSeverity) && ewmaSeverity === rawSeverity;
const modelFallback = predictor?.scores?.classifier?.fallback;
const validResponse = knownClass && validSeverity && validConfidence && validMethod && validScores && validEwmaSeverity && !modelFallback;
let policy = { incident_class: incidentClass || null, severity: null, p_level: null, routing_category: null, outcome: 'invalid' };
if (validResponse && incidentClass === 'normal' && severity === 1) {
  policy = { incident_class: incidentClass, severity, p_level: severityMap[severity], routing_category: null, outcome: 'suppressed' };
} else if (validResponse && incidentClass !== 'normal') {
  policy = { incident_class: incidentClass, severity, p_level: severityMap[severity], routing_category: categoryByClass[incidentClass], outcome: 'routable' };
}
return [{ json: { ...$json, predictor_policy: policy, noise_reason: policy.outcome === 'suppressed' ? 'predictor_normal' : '', context: $('Build IncidentContext').first().json.context } }];

