function clampStr(v, n) {
  const s = String(v == null ? '' : v);
  return s.length <= n ? s : s.slice(0, n);
}
function clampCitations(cites) {
  return (Array.isArray(cites) ? cites : []).slice(0, 8).map(c => ({
    source_id: clampStr((c && c.source_id) || 'unknown', 200),
    source_type: (c && c.source_type) || 'tool_result',
    quote: clampStr((c && c.quote) || 'insufficient data', 500),
  }));
}
const incident = $('Assemble Incident').first().json;
const service = String(incident.service || 'unknown');
const policy = $('Apply Predictor Policy').first().json.predictor_policy;
let evidence = {};
try { evidence = JSON.parse($('Incident Commander').first().json.output || '{}'); } catch (_) {}
const predictor = evidence.predictor || {};
const deep = evidence.langgraph || {};
const retrieval = evidence.rag || deep;
const ownerContext = evidence.service_context || deep;
const flags = [];
const category = policy.routing_category;
let citations = Array.isArray(retrieval.citations) ? retrieval.citations : [];
citations = clampCitations(citations);
if (!citations.length) {
  citations = [{ source_id: 'tool:unavailable', source_type: 'tool_result', quote: 'insufficient data' }];
  flags.push('insufficient_citations');
}
const owner = ownerContext.owner_team || 'unknown';
const escalation = Array.isArray(ownerContext.escalation_path) ? ownerContext.escalation_path : [];
if (owner === 'unknown') flags.push('owner_unverified');
const recommendations = Array.isArray(deep.recommended_steps) && deep.recommended_steps.length
  ? deep.recommended_steps
  : [`Review current health metrics for ${service}.`, 'Compare the signal with recent deployment evidence.'];
return [{ json: {
  incident_id: incident.id,
  category,
  p_level: policy.p_level,
  summary: `Tool-grounded fixture fallback: ${service} classified as ${category}.`,
  probable_cause: clampStr(deep.probable_cause || retrieval.answer || 'Tool evidence requires human analysis.', 1200),
  citations,
  owner_team: owner,
  escalation_path: escalation,
  recommended_steps: recommendations.slice(0, 8),
  confidence: Number(predictor.confidence || deep.confidence || 0.5),
  guardrail_flags: [...new Set(flags)],
  generated_at: new Date().toISOString(),
  model_meta: { provider: 'fixture-fallback', stage: 'A', predictor_incident_class: String(policy.incident_class || ''), predictor_severity: String(policy.severity || ''), evidence: Object.keys(evidence).sort().join(',') }
} }];

function clampStr(v, n) {
  const s = String(v == null ? '' : v);
  return s.length <= n ? s : s.slice(0, n);
}
function clampCitations(cites) {
  return (Array.isArray(cites) ? cites : []).slice(0, 8).map(c => ({
    source_id: clampStr((c && c.source_id) || 'unknown', 200),
    source_type: (c && c.source_type) || 'tool_result',
    quote: clampStr((c && c.quote) || 'insufficient data', 500),
  }));
}
const out = $json.output || $json;
const incident = $('Assemble Incident').first().json;
const policy = $('Apply Predictor Policy').first().json.predictor_policy;
const report = Object.assign({}, out);
report.incident_id = incident.id;
report.category = policy.routing_category;
report.p_level = policy.p_level;
report.generated_at = new Date().toISOString();
report.model_meta = Object.assign({ provider: 'mock-openai-compatible', stage: 'A' }, report.model_meta || {});
report.model_meta.predictor_incident_class = String(policy.incident_class || '');
report.model_meta.predictor_severity = String(policy.severity || '');
report.guardrail_flags = Array.isArray(report.guardrail_flags) ? report.guardrail_flags : [];
report.escalation_path = Array.isArray(report.escalation_path) ? report.escalation_path : [];
report.recommended_steps = (Array.isArray(report.recommended_steps) ? report.recommended_steps : []).slice(0, 8);
report.confidence = Math.max(0, Math.min(1, Number(report.confidence) || 0));
report.summary = clampStr(report.summary, 1200);
report.probable_cause = clampStr(report.probable_cause, 1200);
report.owner_team = clampStr(report.owner_team || 'unknown', 200);
report.citations = clampCitations(report.citations);
report.recommended_steps = (Array.isArray(report.recommended_steps) ? report.recommended_steps : [])
  .map(s => clampStr(s, 500)).slice(0, 8);
return [{ json: report }];
